"""Ch. 5, the chain of fifths: twelve notes generated by pure fifths from Eb to G# (chain positions
-3..8), each folded into the octave above C4, played in chain order; then the same twelve notes
sorted into a chromatic scale, whose semitones alternate unevenly between the limma (90.22 c) and
the apotome (113.69 c)."""
from _lib import freq, seq, silence, tone

C4 = freq(60)


def fold(r):
    while r >= 2:
        r /= 2
    while r < 1:
        r *= 2
    return r


def render():
    chain = [fold(1.5 ** k) for k in range(-3, 9)]
    a = [tone(C4 * r, 0.42) for r in chain]
    b = [tone(C4 * r, 0.36) for r in sorted(chain)] + [tone(2 * C4, 1.2)]
    return seq(a + [silence(0.9)] + b)
